input.content:
/*
 * Targeted compatibility check for the CVE-2021-0941 port.
 *
 * Verifies that BPF_SKB_MAX_LEN (introduced by the port as
 * `#define BPF_SKB_MAX_LEN SKB_MAX_ALLOC`) is a valid integer constant
 * expression built from the target's own skbuff.h macro chain, and that it is
 * usable to initialize a u32 exactly as done in bpf_skb_change_tail().
 *
 * The SKB_* macro definitions below are copied verbatim from the target
 * include/linux/skbuff.h (v4.9.264). This is a supplement to, not a
 * replacement for, a full kernel build.
 */
typedef unsigned int u32;
struct skb_shared_info { char x[320]; };

#define PAGE_SIZE 4096
#define SMP_CACHE_BYTES 64
#define ALIGN(x, a) (((x) + (a) - 1UL) & ~((a) - 1UL))
#define SKB_DATA_ALIGN(X) ALIGN(X, SMP_CACHE_BYTES)
#define SKB_WITH_OVERHEAD(X) \
	((X) - SKB_DATA_ALIGN(sizeof(struct skb_shared_info)))
#define SKB_MAX_ORDER(X, ORDER) \
	SKB_WITH_OVERHEAD((PAGE_SIZE << (ORDER)) - (X))
#define SKB_MAX_ALLOC (SKB_MAX_ORDER(0, 2))

/* Ported definition, as inserted into net/core/filter.c. */
#define BPF_SKB_MAX_LEN SKB_MAX_ALLOC

u32 test_macro(void)
{
	u32 max_len = BPF_SKB_MAX_LEN;

	return max_len;
}

/* Force evaluation as a compile-time constant. */
static char must_be_positive_constant[(BPF_SKB_MAX_LEN) > 0 ? 1 : -1];

